<?php
namespace Nakhostin\PerformanceEngine\JavaScript;
final class JavaScriptRuntimeOptimizer { private $applier; private $safety; public function __construct( ScriptStrategyApplier $applier, ScriptSafetyPolicy $safety ) { $this->applier = $applier; $this->safety = $safety; } public function apply( JavaScriptManifest $manifest, array $context, bool $defer_enabled, bool $unload_enabled ): array { if ( in_array( $context['page_type'] ?? '', array( 'cart', 'checkout', 'account' ), true ) ) { return array( 'deferred' => array(), 'footer' => array(), 'unloaded' => array(), 'reason' => 'protected-commerce-context' ); } $data = $manifest->to_array(); $deferred = array(); if ( $defer_enabled ) { $deferred = $this->applier->apply_defer( $manifest )['applied']; } $footer = array(); foreach ( (array) ( $data['approved_footer'] ?? array() ) as $handle ) { $handle = sanitize_key( (string) $handle ); if ( '' !== $handle && wp_script_add_data( $handle, 'group', 1 ) ) { $footer[] = $handle; } } $unloaded = array(); if ( $unload_enabled ) { $required = (array) ( $data['required'] ?? array() ); foreach ( (array) ( $data['approved_unloads'] ?? array() ) as $handle ) { $handle = sanitize_key( (string) $handle ); if ( '' !== $handle && ! in_array( $handle, $required, true ) && function_exists( 'wp_dequeue_script' ) ) { wp_dequeue_script( $handle ); $unloaded[] = $handle; } } } return array( 'deferred' => $deferred, 'footer' => $footer, 'unloaded' => $unloaded, 'reason' => 'approved-manifest' ); } }
